// 1. Obtenemos datos persistentes
let historial = flow.get("historial_bitacora") || [];
let operarioActual = flow.get("operario_activo") || "Sin registrar";
let turnoActual = flow.get("turno_activo") || "Matutino";

// Convertimos a minúsculas lo que sea que haya llegado para no fallar por mayúsculas
let textoPayload = String(msg.payload || "").toLowerCase();
let textoTopic = String(msg.topic || "").toLowerCase();

// --- 2. DETECTAMOS QUÉ NODO ENVIÓ LA SEÑAL ---

// Si es el botón de GUARDAR (lo detectamos por payload o topic)
if (textoPayload.includes("guardar") || textoTopic.includes("guardar")) {
    let nuevoRegistro = {
        hora: new Date().toLocaleTimeString(),
        fecha: new Date().toLocaleDateString(),
        operario: operarioActual,
        turno: turnoActual,
        evento: "Registro de operación manual",
        estado: "OK"
    };
    historial.unshift(nuevoRegistro);
    if (historial.length > 50) historial.pop();
    flow.set("historial_bitacora", historial);
}
// Si es el botón de REINICIAR (Limpiamos el nombre, la tabla se queda fija)
else if (textoPayload.includes("reiniciar") || textoTopic.includes("reinici")) {
    flow.set("operario_activo", "Sin registrar");
    operarioActual = "Sin registrar";
}
// Si es el campo de NOMBRE
else if (textoTopic.includes("nombre") || msg.topic === "Nombre del operador") {
    operarioActual = msg.payload;
    flow.set("operario_activo", operarioActual);
}
// Si es el menú de TURNO
else if (textoTopic.includes("turno") || msg.topic === "Turno") {
    turnoActual = msg.payload;
    flow.set("turno_activo", turnoActual);
}

// --- 3. ENVIAMOS LOS DATOS A LA PANTALLA ---
msg.payload = {
    registros: historial
};

return msg;

// 1. IP de tu ESP32
let ipESP32 = "192.168.1.50"; 

// 2. Evaluamos qué switch mandó la señal para armar la URL del comando HTTP
if (msg.topic === "bomba_principal") {
    msg.url = "http://" + ipESP32 + "/bomba1?estado=" + (msg.payload ? 1 : 0);
} else if (msg.topic === "bomba_respaldo") {
    msg.url = "http://" + ipESP32 + "/bomba2?estado=" + (msg.payload ? 1 : 0);
} else if (msg.topic === "lampara") {
    msg.url = "http://" + ipESP32 + "/lampara?estado=" + (msg.payload ? 1 : 0);
}

msg.method = "GET";

// 3. Preparamos el objeto de datos (payload) para el panel visual unificado
// (Aquí puedes combinarlo después con los datos reales que llegan de tus entradas superiores de la ESP32)
msg.payload = {
    principalEncendida: msg.topic === "bomba_principal" ? msg.payload : false,
    respaldoEncendido: msg.topic === "bomba_respaldo" ? msg.payload : false,
    lamparaEncendida: msg.topic === "lampara" ? msg.payload : false,
    fallaPrincipal: false,       // Se pondrá en true si la ESP32 detecta una falla
    respaldoHabilitado: false,   // Cambiará a true cuando falle la principal (activa el cuadro gris)
    nivelTanque: 50              // Valor de prueba para el medidor de nivel
};

return msg;

// 1. Obtenemos temperatura y humedad (con valores por defecto si vienen vacíos)
let temperatura = msg.payload.temperatura || 24.0;
let humedad = msg.payload.humedad || 50.0;

// 2. Definimos umbrales de alerta opcionales (ej: temperatura > 35°C es alerta)
let alertaTemp = temperatura >= 35.0;
let alertaHum = humedad >= 80.0;

// 3. Empaquetamos los datos en un objeto limpio para el template visual
msg.payload = {
    temperatura: temperatura.toFixed(1),
    humedad: humedad.toFixed(1),
    alertaTemp: alertaTemp,
    alertaHum: alertaHum,
    // Calculamos porcentajes aproximados para las barras visuales (0 a 50°C para temp, 0 a 100% para humedad)
    porcentajeTemp: Math.min(Math.max((temperatura / 50) * 100, 0), 100),
    porcentajeHum: Math.min(Math.max(humedad, 0), 100)
};

return msg;

// 1. IP de tu ESP32 (cámbiala por la real de tu red)
let ipESP32 = "192.168.1.50"; 

let angulo = msg.payload || 0;

// 2. Armamos la petición HTTP GET hacia el microcontrolador
msg.url = "http://" + ipESP32 + "/valvula?angulo=" + angulo;
msg.method = "GET";

// 3. Preparamos el objeto de datos para el template visual centrado
msg.payload = {
    angulo: angulo,
    // Calculamos el porcentaje de apertura para la barra gráfica (0 a 180 grados)
    porcentajeApertura: Math.min(Math.max((angulo / 180) * 100, 0), 100),
    // Definimos el estado operativo de la válvula
    estadoTexto: angulo === 0 ? "CERRADA" : (angulo >= 180 ? "ABIERTA MÁXIMA" : "REGULANDO")
};

return msg;

// 1. Obtenemos los valores de temperatura o nivel
let temperatura = msg.payload.temperatura || 0.0;
let nivelTanque = msg.payload.nivel || 0;

let limiteTemperatura = 40.0; 
let limiteNivel = 90.0;       

// 2. Evaluamos la condición de peligro
let esPeligro = (temperatura >= limiteTemperatura || nivelTanque >= limiteNivel);
let textoEstado = esPeligro ? "¡ALERTA CRÍTICA DETECTADA!" : "Sistema Operando con Normalidad";

// 3. Empaquetamos en un formato limpio para el template centrado
msg.payload = {
    activo: esPeligro,
    mensaje: textoEstado,
    temperatura: temperatura.toFixed(1),
    nivel: nivelTanque
};

return msg;
